function fileKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_-]{2,100}$/.test(value);
}

const sourceFolder = "YOUR_INPUT_FOLDER_ID";
const destination = "YOUR_OUTPUT_FOLDER_ID";
if (
  !fileKey(sourceFolder) ||
  sourceFolder.startsWith("YOUR_") ||
  !fileKey(destination) ||
  destination.startsWith("YOUR_")
)
  throw new Error("Set both Google Drive folder IDs.");
if ($execution.mode !== "production") return [];
const end = Date.parse($input.first().json.timestamp);
if (!Number.isSafeInteger(end)) throw new Error("Schedule did not provide a valid scan time.");
const staticData = $getWorkflowStaticData("global");
const state = staticData.pdfHtmlScan;
if (state && (!Number.isSafeInteger(state.since) || state.folder !== sourceFolder)) {
  throw new Error(
    "The scan watermark belongs to another Drive folder. Import a new copy to watch it.",
  );
}
if (!state) {
  staticData.pdfHtmlScan = { folder: sourceFolder, since: end };
  return [];
}
const start = state.since;
if (end <= start) return [];
const q = [
  "'" + sourceFolder + "' in parents",
  "trashed = false",
  "mimeType = 'application/pdf'",
  "createdTime >= '" + new Date(start).toISOString() + "'",
  "createdTime < '" + new Date(end).toISOString() + "'",
].join(" and ");
return [{ json: { q, start, end, sourceFolder, destination } }];

function fileKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_-]{2,100}$/.test(value);
}

function pdfEvents(events, isOpenFlow) {
  if (!Array.isArray(events)) throw new Error("Drive did not return file events.");
  const selected = new Map();
  for (const file of events) {
    if (isOpenFlow && (file?.eventType !== "file_created" || file.itemType !== "file")) continue;
    if (file?.mimeType !== "application/pdf" || file.trashed === true) continue;
    const id = isOpenFlow ? file.fileId : file.id;
    if (
      !fileKey(id) ||
      !Array.isArray(file.parents) ||
      file.parents.length !== 1 ||
      !fileKey(file.parents[0])
    ) {
      throw new Error("The new PDF has no verifiable Drive ID and parent.");
    }
    selected.set(id, { id, parent: file.parents[0] });
  }
  return [...selected.values()];
}

const { start, end, sourceFolder, destination } = $(
  "Set folders and select the scan window",
).first().json;
const pages = $input.all();
const tokens = new Set();
const files = [];
for (const [index, item] of pages.entries()) {
  const page = item.json;
  const token = page.body?.nextPageToken;
  if (
    page.statusCode !== 200 ||
    page.body?.incompleteSearch === true ||
    !Array.isArray(page.body?.files) ||
    (token === undefined
      ? index !== pages.length - 1
      : typeof token !== "string" || !token || tokens.has(token) || index === pages.length - 1)
  ) {
    throw new Error(
      "Drive did not return a complete, bounded page sequence. No files were converted.",
    );
  }
  tokens.add(token);
  for (const file of page.body.files) {
    if (file.mimeType !== "application/pdf" || file.trashed === true) continue;
    const time = Date.parse(file.createdTime);
    if (
      time < start ||
      time >= end ||
      !Number.isSafeInteger(time) ||
      file.parents?.[0] !== sourceFolder
    ) {
      throw new Error("Drive returned a PDF outside the requested folder or time window.");
    }
    files.push({ file, index });
  }
}
const matched = pdfEvents(
  files.map((entry) => entry.file),
  false,
).map((source) => ({
  json: { source, destination },
  pairedItem: { item: files.find((entry) => entry.file.id === source.id).index },
}));
$getWorkflowStaticData("global").pdfHtmlScan = { folder: sourceFolder, since: end };
return matched;

function fileKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_-]{2,100}$/.test(value);
}

function driveSource(doc, request, destination) {
  if (!fileKey(destination) || destination.startsWith("YOUR_"))
    throw new Error("Set the destination Drive folder ID.");
  if (
    doc?.id !== request.id ||
    doc.mimeType !== "application/pdf" ||
    doc.trashed === true ||
    !Array.isArray(doc.parents) ||
    doc.parents.length !== 1 ||
    doc.parents[0] !== request.parent
  ) {
    throw new Error("The PDF no longer matches the original Drive file and watched folder.");
  }
  const size = Number(doc.sizeBytes ?? doc.size);
  if (!Number.isSafeInteger(size) || size < 8 || size > 3000000) {
    throw new Error("The input must be a PDF of up to 3,000,000 bytes.");
  }
  if (typeof doc.name !== "string" || !doc.name.trim())
    throw new Error("Drive did not return the source filename.");
  const base = doc.name
    .trim()
    .replace(/[\/\\\u0000-\u001f\u007f]/g, "_")
    .replace(/\.pdf$/i, "")
    .trim();
  const name = (base || "document") + ".html";
  return {
    id: doc.id,
    parent: request.parent,
    destination,
    name,
    size,
    query:
      "'" +
      destination +
      "' in parents and trashed = false and appProperties has { key='pdfHtmlSourceId' and value='" +
      doc.id +
      "' }",
  };
}

const { source, destination } = $("Select newly created PDFs").item.json;
if ($json.statusCode !== 200) throw new Error("Drive did not confirm the source document.");
return { json: driveSource($json.body, source, destination) };

function fileKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_-]{2,100}$/.test(value);
}

function existingHtml(reply, status, doc) {
  if (
    status !== 200 ||
    !Array.isArray(reply?.files) ||
    reply.nextPageToken ||
    reply.files.length > 1
  ) {
    throw new Error(
      "Could not establish a unique prior Drive output. Check the destination before retrying.",
    );
  }
  const current = reply.files[0];
  if (!current) return null;
  if (
    !fileKey(current.id) ||
    current.mimeType !== "text/html" ||
    current.trashed === true ||
    !current.parents?.includes(doc.destination) ||
    current.appProperties?.pdfHtmlSourceId !== doc.id ||
    typeof current.name !== "string"
  ) {
    throw new Error("The marked Drive output does not match this source PDF and folder.");
  }
  return { sourceId: doc.id, driveId: current.id, name: current.name, state: "already_created" };
}

const doc = $("Validate the PDF and target filename").item.json;
const old = existingHtml($json.body, $json.statusCode, doc);
return { json: old ? { ...old, needsConversion: false } : { ...doc, needsConversion: true } };

function requirePdf(bytes, mime, size) {
  const signature = [37, 80, 68, 70, 45];
  if (
    mime?.split(";")[0].toLowerCase() !== "application/pdf" ||
    bytes.length !== size ||
    !signature.every((byte, i) => bytes[i] === byte)
  ) {
    throw new Error("Drive did not return the complete matching PDF.");
  }
}

const doc = $("Validate the PDF and target filename").item.json;
if ($json.statusCode !== 200) throw new Error("Drive did not return the original PDF.");
requirePdf(
  await helpers.getBinaryDataBuffer($itemIndex, "pdf"),
  $input.item.binary?.pdf?.mimeType,
  doc.size,
);
return { json: {}, binary: $input.item.binary };

function temporaryObject(address, maxLifetime) {
  const parts =
    typeof address === "string" &&
    /^https:\/\/(pdf-temp-files\.s3(?:[.-][a-z0-9-]+)?\.amazonaws\.com)(\/[A-Za-z0-9_-]+\/source\.pdf)\?([^\s#"<>\\]+)$/.exec(
      address,
    );
  if (!parts) throw new Error("PDF.co did not return an approved temporary storage URL.");
  const query = parts[3].split("&");
  const count = (key) => query.filter((field) => field.startsWith(key + "="));
  const expires = count("X-Amz-Expires");
  const duration = expires.length === 1 ? Number(expires[0].slice(14)) : NaN;
  if (
    !Number.isInteger(duration) ||
    duration < 1 ||
    duration > maxLifetime ||
    count("X-Amz-Algorithm").length !== 1 ||
    !query.includes("X-Amz-Algorithm=AWS4-HMAC-SHA256") ||
    count("X-Amz-Signature").length !== 1 ||
    !/^X-Amz-Signature=[a-fA-F0-9]{64}$/.test(count("X-Amz-Signature")[0]) ||
    count("X-Amz-Date").length !== 1 ||
    !/^X-Amz-Date=\d{8}T\d{6}Z$/.test(count("X-Amz-Date")[0])
  ) {
    throw new Error("PDF.co did not return an expiring signed storage URL.");
  }
  return parts[1] + parts[2];
}

function uploadTicket(body, status) {
  if (status !== 200 || Number(body?.status) !== 200 || body.error !== false)
    throw new Error("PDF.co did not confirm a temporary upload.");
  if (temporaryObject(body.presignedUrl, 1800) !== temporaryObject(body.url, 3600)) {
    throw new Error("The PDF.co upload and conversion reference different temporary files.");
  }
  return {
    putUrl: body.presignedUrl,
    request: {
      url: body.url,
      pages: "0-",
      inline: true,
      async: false,
      name: "converted.html",
      expiration: 5,
    },
  };
}

return {
  json: uploadTicket($json.body, $json.statusCode),
  binary: $("Check the downloaded PDF bytes").item.binary,
};

if (![200, 204].includes($json.statusCode))
  throw new Error("PDF.co storage did not accept the original bytes.");
return { json: $("Verify the PDF and signed links").item.json.request };

function inlineHtml(body, status) {
  if (
    status !== 200 ||
    Number(body?.status) !== 200 ||
    body.error !== false ||
    typeof body.body !== "string" ||
    !/<(?:!doctype\s+html|html|head|body|meta|style|div|p|table|svg)(?:[\s/>])/i.test(body.body)
  ) {
    throw new Error("PDF.co did not return complete inline HTML.");
  }
  return body.body;
}

function driveUploadMetadata(doc) {
  return {
    name: doc.name,
    mimeType: "text/html",
    parents: [doc.destination],
    appProperties: { pdfHtmlSourceId: doc.id },
  };
}

function driveMultipart(doc, bytes) {
  const metadata = JSON.stringify(driveUploadMetadata(doc));
  let number = 0,
    boundary;
  do {
    boundary = "pdfhtml-" + doc.id.slice(0, 25) + "-" + number++;
  } while (metadata.includes(boundary) || bytes.includes(boundary));
  const data = Buffer.concat([
    Buffer.from(
      "--" +
        boundary +
        "\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n" +
        metadata +
        "\r\n--" +
        boundary +
        "\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n",
    ),
    bytes,
    Buffer.from("\r\n--" + boundary + "--\r\n"),
  ]);
  return { data, contentType: "multipart/related; boundary=" + boundary };
}

const doc = $("Validate the PDF and target filename").item.json;
const bytes = Buffer.from(inlineHtml($json.body, $json.statusCode), "utf8");
if (bytes.length > 2000000) throw new Error("The HTML must fit within 2,000,000 bytes.");
const envelope = driveMultipart(doc, bytes);
return {
  json: {
    size: bytes.length,
    name: doc.name,
    contentType: envelope.contentType,
    html: bytes.toString("base64"),
    multipart: envelope.data.toString("base64"),
  },
};

function fileKey(value) {
  return typeof value === "string" && /^[A-Za-z0-9_-]{2,100}$/.test(value);
}

function driveReceipt(reply, doc, size) {
  if (
    !fileKey(reply?.id) ||
    reply.name !== doc.name ||
    reply.mimeType !== "text/html" ||
    !reply.parents?.includes(doc.destination) ||
    Number(reply.sizeBytes ?? reply.size) !== size
  ) {
    throw new Error("Drive did not confirm the HTML file. Check the destination before retrying.");
  }
  return { sourceId: doc.id, driveId: reply.id, name: reply.name, state: "created" };
}

const doc = $("Validate the PDF and target filename").item.json;
try {
  if (
    ![200, 201].includes($json.statusCode) ||
    $json.body?.appProperties?.pdfHtmlSourceId !== doc.id
  ) {
    throw new Error("Drive did not confirm the HTML file.");
  }
  return {
    json: driveReceipt($json.body, doc, $("Prepare the exact HTML file").item.json.size),
    binary: $("Create the downloadable HTML file").item.binary,
  };
} catch {
  return {
    json: {
      sourceId: doc.id,
      name: doc.name,
      state: "unconfirmed",
      message: "Check the destination before retrying.",
    },
  };
}
